-- Cập nhật nội dung trang About (chạy MỘT lần trong Supabase › SQL Editor)
update settings
set data = jsonb_set(coalesce(data, '{}'::jsonb), '{about}', to_jsonb($about$<h2>Một thế giới nhỏ dành cho những phút giây của riêng bạn</h2><p>Giữa nhịp sống bận rộn, đôi khi chúng ta cần một khoảng lặng để nghỉ ngơi, một niềm vui nho nhỏ để tiếp thêm năng lượng, hay đơn giản là một nơi để tạm quên đi những bộn bề đang chất chứa trong lòng.</p><p>Vinh Làm Game ra đời từ tình yêu dành cho trò chơi điện tử và mong muốn mang những trải nghiệm giải trí gần gũi đến với mọi người. Đây không chỉ là nơi tập hợp những trò chơi do Vinh sáng tạo, mà còn là một không gian nhỏ để bạn tự do khám phá, trải nghiệm và tìm thấy niềm vui theo cách riêng của mình.</p><p>Tại đây, bạn có thể bước vào những cuộc phiêu lưu kỳ thú, đồng hành cùng những nhân vật đáng yêu, khám phá những vùng đất xa lạ hay thử thách bản thân qua những trò chơi vui nhộn. Mỗi trò chơi mang một màu sắc riêng, được hình thành từ những ý tưởng, sở thích và niềm đam mê sáng tạo khác nhau. Có trò chơi dành cho những ai yêu thích khám phá, có trò chơi khơi gợi trí tò mò, cũng có những trải nghiệm đơn giản để bạn thư giãn sau một ngày dài.</p><p>Vinh tin rằng game không nhất thiết phải là những thế giới đồ sộ hay những cuộc cạnh tranh căng thẳng. Đôi khi, niềm vui chỉ đến từ một thử thách nhỏ vừa hoàn thành, một điều bất ngờ vừa khám phá, hay một hành trình khiến ta mỉm cười. Và cũng có những lúc, khi lòng nặng trĩu tâm tư, khi một ngày trôi qua không như mong đợi, việc bước vào một thế giới khác trong vài phút có thể giúp chúng ta tạm gác lại những lo toan, hít thở nhẹ nhàng hơn và tìm lại chút bình yên cho riêng mình.</p><p>Bạn không cần phải vui vẻ mới có thể chơi game. Bạn có thể đến đây khi đang hào hứng, khi muốn tìm kiếm điều mới mẻ, hoặc đơn giản là khi cần một khoảng thời gian để bản thân được nghỉ ngơi. Vinh mong rằng mỗi trò chơi, dù nhỏ bé, đều có thể mang đến cho bạn một khoảnh khắc dễ chịu, một chút cảm hứng hoặc một lý do để mỉm cười.</p><p>Và điều tuyệt vời nhất là bạn không cần phải chuẩn bị gì phức tạp. Không cần tải xuống, không cần cài đặt rườm rà hay sở hữu một thiết bị đặc biệt. Chỉ cần mở trình duyệt trên máy tính hoặc điện thoại, chọn trò chơi mình yêu thích và bắt đầu ngay. Những phút giây giải trí luôn sẵn sàng khi bạn cần.</p><p>Vinh Làm Game vẫn đang trên hành trình phát triển, với nhiều ý tưởng mới và những thế giới đang chờ được khám phá. Mỗi trò chơi là một bước tiến nhỏ trong hành trình theo đuổi đam mê, cũng là cách Vinh chia sẻ niềm vui sáng tạo của mình với mọi người.</p><p>Cảm ơn bạn đã ghé thăm, đã dành thời gian trải nghiệm và trở thành một phần của hành trình này. Nếu bạn có ý tưởng, góp ý hoặc mong muốn hợp tác, Vinh luôn sẵn lòng lắng nghe.</p><blockquote>Vinh Làm Game – Chạm vào thế giới riêng, tìm chút niềm vui mỗi ngày.</blockquote><p><em>Dù hôm nay của bạn thế nào, hy vọng bạn vẫn tìm được một điều nhỏ bé khiến mình mỉm cười.</em></p>$about$::text))
where id = 1;
